package com.hospital.system.service; import com.hospital.system.model.Appointment; import com.hospital.system.dto.AppointmentRequest; import com.hospital.system.repository.*; import com.hospital.system.exception.ApiException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class AppointmentService {private final AppointmentRepository r; private final PatientRepository p; private final DoctorRepository d; public AppointmentService(AppointmentRepository r,PatientRepository p,DoctorRepository d){this.r=r;this.p=p;this.d=d;} public List<Appointment> all(){return r.all();} public Appointment one(Long id){return r.one(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Appointment not found"));} @Transactional public Appointment add(AppointmentRequest x){p.one(x.patientId).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Patient not found"));d.one(x.doctorId).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Doctor not found"));if(r.existsSlot(x.doctorId,x.appointmentDate,x.appointmentTime))throw new ApiException(HttpStatus.CONFLICT,"Doctor slot is already booked");Appointment a=new Appointment();a.patientId=x.patientId;a.doctorId=x.doctorId;a.appointmentDate=x.appointmentDate;a.appointmentTime=x.appointmentTime;a.reason=x.reason;r.add(a);return r.all().stream().filter(v->v.patientId.equals(x.patientId)&&v.doctorId.equals(x.doctorId)&&v.appointmentDate.equals(x.appointmentDate)&&v.appointmentTime.equals(x.appointmentTime)).findFirst().orElseThrow();} public Appointment status(Long id,String s){if(!Set.of("BOOKED","COMPLETED","CANCELLED").contains(s))throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid appointment status");one(id);r.status(id,s);return one(id);} public void delete(Long id){one(id);r.delete(id);} }
